<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Illuminate\Validation\Rule; use Pterodactyl\Facades\Activity; use Illuminate\Support\Facades\Cache; use Pterodactyl\Services\Dezerx\Minecraft\Geyser; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Services\Dezerx\Minecraft\ServerProperties; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\PropertiesWriteRequest; class PropertiesController extends ClientApiController { private const ICON_SIZE = 64; private const STATUS_TTL = 300; public function index(AddonRequest $request, Server $server): JsonResponse { $files = new ServerFiles($server); $values = ServerProperties::read($files); if ($values === null) { return new JsonResponse([ 'available' => false, 'message' => 'There is no server.properties yet. Start the server once and it will write one.', ]); } return new JsonResponse([ 'available' => true, 'fields' => ServerProperties::FIELDS, 'values' => $values, 'running' => $files->powerState() !== 'offline', ]); } public function update(PropertiesWriteRequest $request, Server $server): JsonResponse { $data = $request->validate($this->rules()); $files = new ServerFiles($server); $changes = []; foreach (ServerProperties::FIELDS as $field) { $key = $field['key']; if (!array_key_exists($key, $data['values'])) { continue; } $changes[$key] = match ($field['type']) { 'toggle' => (bool) $data['values'][$key], 'number' => (int) $data['values'][$key], default => (string) ($data['values'][$key] ?? ''), }; } if ($changes === []) { return new JsonResponse([ 'errors' => [['code' => 'NoChanges', 'detail' => 'Nothing to change.']], ], 422); } if (($changes['online-mode'] ?? null) === false) { $changes['enforce-secure-profile'] ??= false; } if (!ServerProperties::write($files, $changes)) { return new JsonResponse([ 'errors' => [['code' => 'WriteFailed', 'detail' => 'server.properties could not be written.']], ], 502); } Activity::event('server:properties.update')->property('keys', array_keys($changes))->log(); return new JsonResponse([ 'saved' => array_keys($changes), 'running' => $files->powerState() !== 'offline', ]); } public function icon(AddonRequest $request, Server $server): JsonResponse { $icon = Cache::remember("server-icon:{$server->uuid}", 300, function () use ($server) { $raw = (new ServerFiles($server))->fileContents('/server-icon.png'); return $raw !== null && str_starts_with($raw, "\x89PNG") ? 'data:image/png;base64,' . base64_encode($raw) : ''; }); return new JsonResponse(['icon' => $icon !== '' ? $icon : null]); } public function uploadIcon(PropertiesWriteRequest $request, Server $server): JsonResponse { $request->validate(['icon' => ['required', 'image', 'max:4096']]); $png = $this->square($request->file('icon')->getRealPath()); if ($png === null) { return new JsonResponse([ 'errors' => [['code' => 'BadImage', 'detail' => 'That image could not be read.']], ], 422); } if (!(new ServerFiles($server))->writeFile('/server-icon.png', $png)) { return new JsonResponse([ 'errors' => [['code' => 'WriteFailed', 'detail' => 'The icon could not be saved.']], ], 502); } Cache::forget("server-icon:{$server->uuid}"); Activity::event('server:properties.icon')->log(); return new JsonResponse(['icon' => 'data:image/png;base64,' . base64_encode($png)]); } public function deleteIcon(PropertiesWriteRequest $request, Server $server): JsonResponse { (new ServerFiles($server))->deletePaths('/', ['server-icon.png']); Cache::forget("server-icon:{$server->uuid}"); Activity::event('server:properties.icon')->property('deleted', true)->log(); return new JsonResponse(['icon' => null]); } public function geyser(AddonRequest $request, Server $server): JsonResponse { $status = Cache::get("geyser:{$server->uuid}"); if ($status === null) { $status = Geyser::status(new ServerFiles($server)); if ($status['supported']) { Cache::put("geyser:{$server->uuid}", $status, self::STATUS_TTL); } } return new JsonResponse($status); } public function installGeyser(PropertiesWriteRequest $request, Server $server): JsonResponse { $files = new ServerFiles($server); Cache::forget("geyser:{$server->uuid}"); $properties = ServerProperties::read($files) ?? []; $result = Geyser::install($files, ($properties['online-mode'] ?? 'true') === 'false'); if (!($result['ok'] ?? false)) { return new JsonResponse([ 'errors' => [['code' => 'GeyserFailed', 'detail' => $result['message']]], ], 422); } ServerProperties::write($files, ['enforce-secure-profile' => false]); Activity::event('server:properties.geyser')->log(); return new JsonResponse($result, 202); } private function square(string $path): ?string { $source = @imagecreatefromstring((string) @file_get_contents($path)); if ($source === false) { return null; } $width = imagesx($source); $height = imagesy($source); $side = min($width, $height); $icon = imagecreatetruecolor(self::ICON_SIZE, self::ICON_SIZE); imagealphablending($icon, false); imagesavealpha($icon, true); imagefill($icon, 0, 0, imagecolorallocatealpha($icon, 0, 0, 0, 127)); imagecopyresampled( $icon, $source, 0, 0, intdiv($width - $side, 2), intdiv($height - $side, 2), self::ICON_SIZE, self::ICON_SIZE, $side, $side, ); ob_start(); imagepng($icon); $png = (string) ob_get_clean(); imagedestroy($icon); imagedestroy($source); return $png; } private function rules(): array { $rules = ['values' => ['required', 'array']]; foreach (ServerProperties::FIELDS as $field) { $rules['values.' . $field['key']] = match ($field['type']) { 'toggle' => ['sometimes', 'boolean'], 'number' => ['sometimes', 'integer', "min:{$field['min']}", "max:{$field['max']}"], 'choice' => ['sometimes', 'string', Rule::in($field['options'])], default => ['sometimes', 'nullable', 'string', 'max:' . ($field['max'] ?? 240)], }; } return $rules; } } 